import type { FallLocationWarning } from '../../models/FallLocationWarning';
import {
  FallWarningCurrentStatus,
  FallWarningProposalStatus,
} from '../../models/FallLocationWarning';

/** POST body — only writable fields; optional text defaults to ''. */
export function toCreateFallLocationWarningPayload(
  data: Partial<FallLocationWarning>,
) {
  return {
    surveyDate:          data.surveyDate ?? '',
    location:            data.location ?? '',
    causes:              (data.causes ?? []).map((c) => c.trim()).filter(Boolean),
    detailedDescription: data.detailedDescription ?? '',
    preFixPhotoUrl:      data.preFixPhotoUrl ?? null,
    proposedFix:         data.proposedFix ?? '',
    proposalStatus:      data.proposalStatus ?? FallWarningProposalStatus.NotProposed,
    reSurveyDate:        data.reSurveyDate ?? null,
    currentStatus:       data.currentStatus ?? FallWarningCurrentStatus.NotFixed,
    postFixPhotoUrl:     data.postFixPhotoUrl ?? null,
    notes:               data.notes ?? null,
    departmentId:        data.departmentId ?? null,
    departmentName:      data.departmentName ?? '',
  };
}

/** PUT body — writable fields only (no id / audit / idCode). */
export function toUpdateFallLocationWarningPayload(
  data: Partial<FallLocationWarning>,
) {
  return {
    surveyDate:          data.surveyDate,
    location:            data.location,
    causes:              data.causes?.map((c) => c.trim()).filter(Boolean),
    detailedDescription: data.detailedDescription ?? '',
    preFixPhotoUrl:      data.preFixPhotoUrl,
    proposedFix:         data.proposedFix ?? '',
    proposalStatus:      data.proposalStatus,
    reSurveyDate:        data.reSurveyDate,
    currentStatus:       data.currentStatus,
    postFixPhotoUrl:     data.postFixPhotoUrl,
    notes:               data.notes,
    departmentId:        data.departmentId,
    departmentName:      data.departmentName,
  };
}
