import React, { useEffect } from 'react';
import { Link, Outlet, useLocation } from 'react-router-dom';
import { navigateToUrl } from 'single-spa';
import { useAppDispatch, useAppSelector } from '../../../store/hooks';
import { useResponsive } from '../../../hooks/useResponsive';
import { useShellTopbarFlags } from '../../../hooks/useShellTopbarFlags';
import { fetchUnreadCount } from '../../../store/slices/notificationSlice';
import { fetchUnreadMessageCount } from '../../../store/slices/messagesInboxSlice';
import { ErrorBoundary } from '../ErrorBoundary';
import {
  AppSwitcher,
  AppDef,
  AppId,
  MessageCenter,
  NotificationCenter,
  ReduxToastContainer,
} from '@linm-soft-org/linm-web-common-components';
import { signalRService } from '../../../services/signalr';
import { showDevNav, isStandalone } from '../../../dev/isStandalone';
import { isScykShellPath, scykRoutes } from '../../../config/scykRoutes';
import styles from './AppLayout.module.css';

const getActiveApp = (pathname: string): AppId => {
  if (isScykShellPath(pathname)) return 'medical-incidents';
  return 'task-management';
};

const getPageTitle = (pathname: string, activeApp: AppId): string => {
  if (pathname === scykRoutes.incidents.list) return 'Danh Sách Sự Cố';
  if (pathname === scykRoutes.incidents.new) return 'Báo Cáo Sự Cố Mới';
  if (pathname === scykRoutes.dailyReports.list) return 'Báo Cáo Hàng Ngày';
  if (pathname === scykRoutes.dailyReports.new) return 'Báo Cáo Hàng Ngày Mới';
  if (pathname === scykRoutes.monthlyReports.list) return 'Báo Cáo Tổng Hợp Hàng Tháng';
  if (pathname === scykRoutes.monthlyReports.new) return 'Báo Cáo Tổng Hợp Mới';
  if (pathname.startsWith('/scyk/bc/tong-hop-thang/')) return 'Báo Cáo Tổng Hợp Hàng Tháng';
  if (pathname === scykRoutes.reports.summary) return 'Báo Cáo Thống Kê';
  if (pathname === scykRoutes.reports.serviceMismatch) return 'Báo Cáo Nhầm Dịch Vụ';
  if (pathname === scykRoutes.reports.fall) return 'Báo Cáo Sự Cố Té Ngã';
  if (pathname.startsWith('/scyk/su-co/')) return 'Chi Tiết Sự Cố';
  if (pathname === scykRoutes.fallWarnings.list) return 'Cảnh Báo Té Ngã';
  if (pathname === scykRoutes.fallWarnings.new) return 'Thêm Cảnh Báo Té Ngã';
  if (pathname.startsWith('/scyk/canh-bao/te-nga/')) return 'Chi Tiết Cảnh Báo Té Ngã';
  if (pathname.startsWith('/dev')) return 'Dev Navigation';
  return activeApp === 'medical-incidents' ? 'QLCV & SC Y Khoa' : 'Quản lý công việc';
};

export const AppLayout: React.FC = () => {
  const location = useLocation();
  const dispatch = useAppDispatch();
  const currentUser = useAppSelector((state) => state.auth.user);
  const { enableMessage, enableNotification } = useShellTopbarFlags();

  const { isMobile } = useResponsive();

  const activeApp = getActiveApp(location.pathname);
  const pageTitle = getPageTitle(location.pathname, activeApp);

  const handleAppSwitch = (app: AppDef) => navigateToUrl(app.homeRoute);
  const handleShellNavigate = (path: string) => navigateToUrl(path);

  useEffect(() => {
    if (isStandalone) return;
    window.dispatchEvent(new CustomEvent('linm:nav:set-title', { detail: pageTitle }));
  }, [pageTitle, location.pathname]);

  useEffect(() => {
    if (!currentUser?.id || isStandalone) return;
    if (enableNotification) dispatch(fetchUnreadCount());
    if (enableMessage) dispatch(fetchUnreadMessageCount());
  }, [currentUser?.id, dispatch, enableMessage, enableNotification]);

  useEffect(() => {
    if (!currentUser?.id || isStandalone || !enableNotification) return;
    return signalRService.onReconnected(() => {
      dispatch(fetchUnreadCount());
      if (enableMessage) dispatch(fetchUnreadMessageCount());
    });
  }, [currentUser?.id, dispatch, enableMessage, enableNotification]);

  useEffect(() => {
    if (isStandalone || !enableNotification) return;
    const handler = () => {
      if (document.visibilityState === 'visible' && currentUser?.id) {
        dispatch(fetchUnreadCount());
      }
    };
    document.addEventListener('visibilitychange', handler);
    return () => document.removeEventListener('visibilitychange', handler);
  }, [currentUser?.id, dispatch, enableNotification]);

  return (
    <div
      className={[
        styles.main,
        isStandalone ? styles.mainStandalone : styles.mainEmbedded,
      ].filter(Boolean).join(' ')}
      data-modal-root
    >
      {isStandalone && (
        <header className={styles.topbar}>
          <div className={styles.topbarLeft}>
            {isMobile && (
              <button
                type="button"
                className={styles.menuButton}
                onClick={() => window.dispatchEvent(new CustomEvent('linm:nav:toggle-mobile'))}
                aria-label="Mở menu"
              >
                <i className="fas fa-bars" />
              </button>
            )}
            <AppSwitcher activeApp={activeApp} onSwitch={handleAppSwitch} />
            <h1 className={styles.title}>{pageTitle}</h1>
          </div>
          <div className={styles.topbarRight}>
            {showDevNav && !location.pathname.startsWith('/dev') && (
              <Link to="/dev" className={styles.devLink} title="Dev Navigation">
                <i className="fas fa-wrench" aria-hidden />
              </Link>
            )}
            {enableMessage && <MessageCenter onNavigate={handleShellNavigate} />}
            {enableNotification && <NotificationCenter onNavigate={handleShellNavigate} />}
          </div>
        </header>
      )}
      <div className={styles.content}>
        <ErrorBoundary>
          <Outlet />
        </ErrorBoundary>
      </div>
      {isStandalone && <ReduxToastContainer />}
    </div>
  );
};

export default AppLayout;
